    configs=[
        triton.Config({}, num_warps=4, num_stages=1, maxnreg=64),
        triton.Config({}, num_warps=4, num_stages=1, maxnreg=96),
        triton.Config({}, num_warps=8, num_stages=1, maxnreg=64),
        # ...
    ],
    key=[],
)
@triton.jit
def kernel(arg_A, arg_B, out_ptr0):
    # same body — compiler spills excess registers to local memory
    for k in range(0, K, BLOCK_K):
        a = tl.load(A_ptr + ...)
        b = tl.load(B_ptr + ...)
        acc += tl.dot(a, b)

